def checkExprDecls(expr: Expr, expected: Option[Type]): Expr = expr match {

  case d@SLocalVarDecl(SExprInfo(span, paren,_), body, lhses, None) => {
    // Extend typechecker with new bindings from the RHS types
    val newChecker = this.extend(lhses)
    // Check the LetExpr body.
    val (newBody, newType) = checkLetBody(newChecker, body, expected).getOrElse(return expr)
    SLocalVarDecl(SExprInfo(span, paren, newType), newBody, lhses, None)
  }

  case d@SLocalVarDecl(SExprInfo(span, paren,_), body, lhses, Some(rhs))
    if (lhses.length > 1 && rhs.isInstanceOf[TupleExpr] &&
        rhs.asInstanceOf[TupleExpr].getExprs.size == lhses.length) => {
      val pairs =
        (lhses, toListFromImmutable(rhs.asInstanceOf[TupleExpr].getExprs)).zipped.map((lv, r) => toOption(lv.getIdType) match {
          case Some(pt) => pt match {
            case p@SPattern(_,_,_) =>
              bug("Pattern should be desugared away: " + p)
            case t@SType(_) =>
        //System.out.println("Losing rhs: " + rhs)
              (lv, checkExpr(r, t, errorString("Right-hand side", "declared")))
          }
          case None => lv match {
            case SLValue(info, name, mods, None, mut) =>
              val newR = defaultNumeral(checkExpr(r, None))
              (SLValue(info, name, mods,
                       Some(getType(newR).getOrElse(return expr)), mut),
               newR)
            case _ => return expr
          }
        })
      val (newLhses, newRhses) = (pairs.map(_._1), pairs.map(_._2))
      val newRhs = EF.makeTupleExpr(span, toJavaList(newRhses))
      // Extend typechecker with new bindings from the RHS types
      val newChecker = this.extend(newLhses)
      // Check the LetExpr body
      val (newBody, newType) = checkLetBody(newChecker, body, expected).getOrElse(return expr)
    SLocalVarDecl(SExprInfo(span, paren, newType), newBody, newLhses, Some(newRhs))
  }

  case d@SLocalVarDecl(SExprInfo(span, paren, _), body, lhses, Some(rhs)) => {
    // Gather declared types of LHS as a big tuple type.
    val declaredTypes = lhses.flatMap(lv => toOption(lv.getIdType) match {
                                      case Some(pt) => pt match {
                                        case p@SPattern(_,_,_) =>
                                          bug("Pattern should be desugared away: " + p)
                                        case t@SType(_) => Some(t)
                                      }
                                      case None => None
                                      })
    val declaredType =
      if (declaredTypes.length == lhses.length)
        Some(NF.makeMaybeTupleType(NU.getSpan(d), toJavaList(declaredTypes)))
      else
        None
    // Type check the RHS, expecting the declared type.
    val (newLhses, newRhs) = declaredType match {
      // If there is a declared type, just check the RHS expecting that.
      case Some(typ) =>
        //System.out.println("Losing rhs: " + rhs)
        (lhses, checkExpr(rhs, typ, errorString("Right-hand side", "declared")))
      // If there is not a declared type, check the RHS and assign LHS types
      // from that.
      case None =>
        // Check the RHS.
        val newRhs = defaultNumeral(checkExpr(rhs, None))
        val rhsType = getType(newRhs).getOrElse(return expr)
        // Get all the LHSes and their corresponding RHS type.
        val lhsAndRhsTypes = lhses match {
          case List(lhs) => List((lhs, rhsType))
          case _ =>
            if (!enoughElementsForType(lhses, rhsType)) {
              signal(expr, "Right-hand side has type %s, but left-hand side is a tuple of %d variables.".format(rhsType, lhses.size))
              return expr
            }
            zipWithRhsType(lhses, rhsType)
        }
        // Map over the LHS/RHS pairs to create the new list of LHSes.
        val newLhses = lhsAndRhsTypes.map {
          // No type on LHS -- just insert it.
          case (SLValue(info, name, mods, None, mut), rhsType) =>
            SLValue(info, name, mods, Some(rhsType), mut)
          case (lhs, _) => lhs
        }
        // Where some of the names declare a type, the RHS is checked
        // again, expecting each name's type, as where all of them do.
        val checkedRhs =
          if (declaredTypes.isEmpty) newRhs
          else {
            val nameTypes = lhsAndRhsTypes.map {
              case (SLValue(_, _, _, Some(t@SType(_)), _), _) => t
              case (_, rhsType) => rhsType
            }
            checkExpr(rhs, NF.makeTupleType(NU.getSpan(d), toJavaList(nameTypes)),
                      errorString("Right-hand side", "declared"))
          }
        (newLhses, checkedRhs)
      }
    // Extend typechecker with new bindings from the RHS types
    val newChecker = this.extend(newLhses)
    // Check the LetExpr body.
    val (newBody, newType) = checkLetBody(newChecker, body, expected).getOrElse(return expr)
    SLocalVarDecl(SExprInfo(span, paren, newType), newBody, newLhses, Some(newRhs))
  }

  case SLetFn(SExprInfo(span, paren, _), body, fns) => {
    // Extend with functions
    val fnIndices = fns.map(new DeclaredFunction(_))
    val newChecker = this.extendWithListOfFunctions(fnIndices)

    // Prime functionals to infer return types.
    Thunker.primeFunctionals(fnIndices, STypeCheckerFactory.makeTryChecker(newChecker))

    // Check the contained body and FnDecls.

    case _ => false
  }
  def isParenedExprItem(item: MathItem) = item match {
    case SParenthesisDelimitedMI(_,_) => true
    case _ => false
  }
  def isFunctionItem(item: MathItem) = item match {
    case SParenthesisDelimitedMI(_,e) => isArrows(checkExpr(e))
    case SNonParenthesisDelimitedMI(_,e) => isArrows(checkExpr(e))
    case _ => false
  }
  def expectParenedExprItem(item: MathItem) =
    if ( ! isParenedExprItem(item) )
      syntaxError(item, "Argument to function must be parenthesized.")
  def expectExprMI(item: MathItem) =
    if ( ! isExprMI(item) )
      syntaxError(item, "Item at this location must be an expression, not an operator.")
  // items is not an empty list.
  def associateMathItems(first: Expr,
                         items: List[MathItem]): (Expr, List[MathItem]) = {
    /* For each expression element (i.e., not a subscripting, exponentiation
     * or postfix operator), determine whether it is a function.
     * If some function element is immediately followed by an expression
     * element then, find the first such function element, and call the
     * next element the argument.
     */
    // find the left-most function
    val (prefix, others) = items.span((e:MathItem) =>
                                      !isFunctionItem(e))
    others match {
      case fn::arg::suffix => arg match {
        // It is a static error if either the argument is not parenthesized,
        case SNonParenthesisDelimitedMI(_,e) =>
          syntaxError(e, "Tightly juxtaposed expression should be parenthesized.")
          (first, Nil)
        case SParenthesisDelimitedMI(i,e) => {
          // or the argument is immediately followed by a non-expression element.
          suffix match {
            case third::more =>
              if ( ! isExprMI(third) )
                syntaxError(third, "An expression is expected.")
            case _ =>
          }
          // Otherwise, replace the function and argument with a single element
          // that is the application of the function to the argument.  This new
          // element is an expression.  Reassociate the resulting sequence
          // (which is one element shorter)
          val fnApp =
            new NonParenthesisDelimitedMI(i,
                                          EF.make_RewriteFnApp(fn.asInstanceOf[ExprMI].getExpr,
                                                                        arg.asInstanceOf[ExprMI].getExpr))
          associateMathItems( first, prefix++(fnApp::suffix) )
        }
        case _ => reassociateMathItems( first, items )
      }
      case _ => reassociateMathItems( first, items )
    }
  }
  // items is not an empty list.
  def reassociateMathItems(first: Expr, items: List[MathItem]) = {
    val (left, right) = items.span( isExprMI )
    val head = left match {
      case Nil => first
      case _ =>
        if ( isExprMI(left.last) )
          left.last.asInstanceOf[ExprMI].getExpr
        else {
          syntaxError(left.last, "An expression is expected.")
          first
        }
    }
    right match {
    /* If there is any non-expression element (it cannot be the first element)
     * then replace the first such element and the element
     * immediately preceeding it (which must be an expression) with
     * a single element that does the appropriate operator application.
     * This new element is an expression.  Reassociate the resulting
     * sequence (which is one element shorter.)
     */
      case item::suffix => {
        val newExpr = item match {
          case SExponentiationMI(_,op,expr) =>
            EF.makeOpExpr(op, head, toJavaOption(expr))
          // A subscript is a call of the subscript operator's method, as
          // the desugaring before the checker writes every subscript
          // expression (AssignmentAndSubscriptDesugarer.desugarSubscriptExpr).
          case SSubscriptingMI(_,op,exprs,sargs) =>
            EF.makeMethodInvocation(EF.makeSubscriptExpr(span, head,
                                                         toJavaList(exprs), some(op),
                                                         toJavaList(sargs)),
                                    head, op, toJavaList(sargs),
                                    EF.makeMaybeTupleExpr(NU.getSpan(op), toJavaList(exprs)))
          case _ =>
            syntaxError(item, "Non-expression element is expected.")
            head
        }
        left match {
          case Nil => associateMathItems(newExpr, suffix)
          case _ =>
            val exp = new NonParenthesisDelimitedMI(newExpr.getInfo, newExpr)
            associateMathItems(first, left.dropRight(1)++(exp::suffix))
        }
      }
      case _ => (first, items)
    }
  }

  // HANDLE THE FRONT ITEM
  val newFront = checkExpr(front)
  getType( newFront ) match {
    case None => front
    case Some(t) =>
      // If front is a fn followed by an expr, we reassociate
      if ( isArrows(t) && isExprMI(second) ) {
        // It is a static error if either the argument is not parenthesized,
        expectParenedExprItem(second)
        // static error if the argument is immediately followed by
        // a non-expression element.
        remained match {
          case hd::tl => expectExprMI(hd)
          case Nil =>
        }
        // Otherwise, make a new MathPrimary that is one element shorter,
        // and recur.
        val fn = EF.make_RewriteFnApp(front,
                                      second.asInstanceOf[ExprMI].getExpr)
        checkExpr(SMathPrimary(info, multi, infix, fn, remained), expected)
      // THE FRONT ITEM WAS NOT A FN FOLLOWED BY AN EXPR, REASSOCIATE REST
      } else {
        val (head, tail) = associateMathItems( newFront, rest )
        // Where every item applied in turn to the front, as in x[5]^2, the
        // primary is that one application, which no juxtaposition takes.
        if ( tail.isEmpty ) return checkExpr(head, expected)
        // Otherwise, left-associate the sequence, which has only expression
        // elements, only the last of which may be a function.
        val newTail = tail.map( (e:MathItem) =>
                                if ( ! isExprMI(e) ) {
                                  syntaxError(e, "An expression is expected.")
                                  EF.makeVoidLiteralExpr(span)
                                } else e.asInstanceOf[ExprMI].getExpr )
        // Treat the sequence that remains as a multifix application of
        // the juxtaposition operator.
        // The rules for multifix operators then apply: the multifix
        // application is used where it applies, whatever the expected type.
        // Either way the application is the juxtaposition's value, so it
        // has the juxtaposition's expected type, as for a loose juxtaposition.
        val multiOp = EF.makeOpExpr(span, multi, toJavaList(head::newTail))
        val tryChecker = STypeCheckerFactory.makeTryChecker(this)
        val multi_op_expr = tryChecker.tryCheckExpr(multiOp).map { plain =>
          if (expected.isEmpty) plain
          else tryChecker.tryCheckExpr(multiOp, expected).getOrElse(plain) }
        multi_op_expr.getOrElse {
          // If not, left-associate as binary applications, the outermost of
          // which is the juxtaposition's value.
          newTail match {
            case Nil => head
            case _ =>
              val inner = newTail.init.foldLeft(head) { (r:Expr, e:Expr) =>
                checkExpr(EF.makeOpExpr(NU.spanTwo(r, e), infix, r, e))
              }
              checkExpr(EF.makeOpExpr(NU.spanTwo(inner, newTail.last), infix, inner, newTail.last),
                        expected)
          }
        }
      }
  }
}

// First try to type check this expression as a multifix operator expression.
// If that fails, type check it as some number of applications of the infix
// operator, left associatively.
// As for a loose juxtaposition, the multifix application is used where it
// applies, whatever the expected type; either way the application is the
// expression's value, so it has the expression's expected type.
case SAmbiguousMultifixOpExpr(info, infixOp, multifixOp, args) => {
  def infixAssociate(e1: Expr, e2: Expr) = SOpExpr(info, infixOp, List(e1, e2))
  val multiOp = SOpExpr(info, multifixOp, args)
  val tryChecker = STypeCheckerFactory.makeTryChecker(this)
  tryChecker.tryCheckExpr(multiOp).map { plain =>
    if (expected.isEmpty) plain
    else tryChecker.tryCheckExpr(multiOp, expected).getOrElse(plain) }.
    getOrElse(checkExpr(args.reduceLeft(infixAssociate), expected))
